"""Conservative closed-loop Last10mPolicy with safety gating, target
confirmation, steering hysteresis, and bounded reacquisition memory.
"""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Choose a safe target-directed action using confidence and short-term hysteresis."""
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    previous_action = memory.get("previous_action", "")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    scan_steps = int(memory.get("scan_steps", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["previous_action"] = action
        return action, confidence, memory

    # Safety is an unconditional hard gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )

    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            scan_steps += 1
        else:
            scan_steps = 1

        if scan_steps >= 2:
            scan_direction = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
            scan_steps = 0
        memory["scan_direction"] = scan_direction
        memory["scan_steps"] = scan_steps
        return emit(scan_direction, 0.75, "SEARCH")

    memory["scan_steps"] = 0

    # Require a fresh track to settle, but avoid repeatedly slowing a confirmed one.
    if track_age < 2 and state not in {"LOCKED", "APPROACH"}:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if heading_error <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        action = "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        return emit(action, 0.88, "APPROACH")

    # Steering hysteresis suppresses left/right chatter near the centerline.
    steer = None
    if previous_action == "VEER_LEFT" and bearing < 6.0:
        steer = "VEER_LEFT"
    elif previous_action == "VEER_RIGHT" and bearing > -6.0:
        steer = "VEER_RIGHT"
    elif bearing < -12.0 and observation["corridor_left"]:
        steer = "VEER_LEFT"
    elif bearing > 12.0 and observation["corridor_right"]:
        steer = "VEER_RIGHT"

    if steer == "VEER_LEFT" and observation["corridor_left"]:
        return emit(steer, 0.89, "APPROACH")
    if steer == "VEER_RIGHT" and observation["corridor_right"]:
        return emit(steer, 0.89, "APPROACH")
    if observation["corridor_center"]:
        return emit("FORWARD", 0.91, "APPROACH")
    if observation["corridor_left"]:
        return emit("VEER_LEFT", 0.82, "APPROACH")
    if observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.82, "APPROACH")
    return emit("STOP", 0.98, "STOPPED")


# EVOLVE-BLOCK-END
